// Emits the Lore test-command `list` shape: a single JSON array of
// {id, name, file} objects, one per test, and nothing else on stdout.
// Jest cannot resolve test names without executing them - there is no
// dry-run - so the suite is run once with --json written to a temp file and
// progress sent to stderr, keeping stdout pure.
// The id is "<repo-relative-file>::<full test name>" - stable across runs,
// and exactly what the run command's {selector} splits back apart.
import {execFileSync} from 'node:child_process';
import {readFileSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join, relative} from 'node:path';
import process from 'node:process';

const reportFile = join(tmpdir(), `hal-engine-jest-report-${process.pid}.json`);

try {
  execFileSync('npx', ['jest', '--json', `--outputFile=${reportFile}`], {
    cwd: process.cwd(),
    stdio: ['ignore', 'ignore', 'inherit'],
    // The suite runs as ESM; jest needs the flag in every spawn, not just npm test.
    env: {...process.env, NODE_OPTIONS: `${process.env.NODE_OPTIONS ?? ''} --experimental-vm-modules`.trim()},
  });
} catch {
  // A failing test still produces a full report, and listing must not depend
  // on the suite being green. An unreadable report below is the real failure.
}

let report;

try {
  report = JSON.parse(readFileSync(reportFile, 'utf8'));
} catch (error) {
  process.stderr.write(`jest produced no readable report at ${reportFile}: ${error.message}\n`);
  process.exit(1);
} finally {
  rmSync(reportFile, {force: true});
}

const tests = report.testResults.flatMap(suite => {
  const file = relative(process.cwd(), suite.name);

  return suite.assertionResults.map(assertion => ({
    id: `${file}::${assertion.fullName}`,
    name: assertion.fullName,
    file,
  }));
});

process.stdout.write(`${JSON.stringify(tests)}\n`);

import {jest} from '@jest/globals';
import net from 'node:net';
import {setLogger} from '../shared/logger.js';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import type {ExtWebSocket} from './ws/connectionHandler.js';
import type {ChatSession} from '../types/session.js';
import type {SessionStore} from '../types/sessionStore.js';
import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
import type {WsAuthenticator} from '../types/auth.js';

// The defect this pins is an omission: both hooks are declared on HalServerOptions, and one was never forwarded.

const settle = () => new Promise<void>(resolve => setTimeout(resolve, 0));

const harness = (onConnect?: (session: ChatSession) => void) => {
  const sessionStore = {
    create: (sessionId: string, userId: string | number): ChatSession => ({sessionId, userId, entries: []}),
    delete: () => true,
  } as unknown as SessionStore;

  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth: jest.fn() as unknown as WsAuthenticator,
    sessionStore,
    orchestrator: {} as ChatOrchestrator,
    onConnect,
  });

  const ws = {
    userId: 'u1',
    isAlive: true,
    send: () => undefined,
    on: () => undefined,
  } as unknown as ExtWebSocket;

  return {hal, ws};
};

describe('createServer hook wiring', () => {
  it('forwards onConnect to the connection handler', async () => {
    const seen: ChatSession[] = [];
    const {hal, ws} = harness(session => void seen.push(session));

    hal.wss.emit('connection', ws);
    await settle();
    hal.wss.emit('close');

    expect(seen.length).toBe(1);
  });

  it('accepts a server configured without either hook', async () => {
    const {hal, ws} = harness();

    hal.wss.emit('connection', ws);
    await settle();
    hal.wss.emit('close');

    expect(hal.wss.listenerCount('connection')).toBe(1);
  });
});

// An EventEmitter with no `error` listener throws, so a socket error on a running server ended the process.
describe('a server error after start', () => {
  const engineLines: string[] = [];

  beforeEach(() => {
    engineLines.length = 0;
    const collect = (_category: string, message: string) => void engineLines.push(message);
    setLogger({debug: collect, info: collect, warn: collect, error: collect});
  });

  afterEach(() => {
    setLogger();
  });

  const started = async () => {
    const {hal} = harness();
    await hal.start(0);
    return hal;
  };

  // A stopped engine and a port something else holds, so the next start is refused by the OS.
  const refusedStart = async () => {
    const hal = await started();
    await hal.stop();
    const blocker = net.createServer();
    await new Promise<void>(resolve => blocker.listen(0, resolve));
    const taken = (blocker.address() as net.AddressInfo).port;
    const release = () => new Promise<void>(resolve => blocker.close(() => resolve()));
    return {hal, taken, release};
  };

  it('is reported rather than ending the process', async () => {
    const hal = await started();

    hal.server.emit('error', new Error('late failure'));
    await hal.stop();

    expect(engineLines).toContain('server error after start');
  });

  it('leaves exactly one listener behind, however many times the server is restarted', async () => {
    const hal = await started();
    await hal.stop();
    await hal.start(0);

    const count = hal.server.listenerCount('error');
    await hal.stop();

    expect(count).toBe(1);
  });

  it('is still reported after stop, because an error with no handler ends the process', async () => {
    const hal = await started();
    await hal.stop();

    hal.server.emit('error', new Error('after stop'));

    expect(engineLines).toContain('server error after start');
  });

  it('is not reported for a start that was cleanly refused, because nothing was running', async () => {
    const {hal, taken, release} = await refusedStart();

    await hal.start(taken).catch((error: NodeJS.ErrnoException) => engineLines.push(`rejected ${error.code}`));
    await release();

    expect(engineLines).toEqual(['HAL Engine started', 'rejected EADDRINUSE']);
  });

  it('stops cleanly after a refused start, so a finally block does not turn one failure into two', async () => {
    const {hal, taken, release} = await refusedStart();
    await hal.start(taken).catch(() => undefined);

    const stopped = hal.stop().then(
      () => 'resolved',
      (error: NodeJS.ErrnoException) => `rejected ${error.code}`
    );
    await release();

    await expect(stopped).resolves.toBe('resolved');
  });

  it('refuses a second start without stripping the running server of its handler', async () => {
    const hal = await started();

    await hal.start(0).catch((error: Error) => engineLines.push(`rejected ${error.message}`));
    hal.server.emit('error', new Error('after the refused start'));
    await hal.stop();

    expect(engineLines).toEqual([
      'HAL Engine started',
      'rejected HAL Engine is already started',
      'server error after start',
    ]);
  });
});
import net from 'node:net';
import {createHalEngine} from './config.js';
import {log, setLogger} from './shared/logger.js';
import type {Logger} from './shared/logger.js';
import type {ChatSession} from './types/session.js';
import type {WsAuthenticator} from './types/auth.js';

// Both options below are declared on HalEngineConfig and were dropped at the forwarding site.

const base = {
  provider: {type: 'mock' as const},
  prompt: {identity: 'test'},
  auth: {ws: (async () => null) as unknown as WsAuthenticator},
};

describe('createHalEngine forwarding', () => {
  it('forwards an orchestrator hook, so one passed through the config actually fires', async () => {
    const seen: string[] = [];
    const engine = createHalEngine({
      ...base,
      orchestrator: {hooks: {beforeSession: async () => void seen.push('beforeSession')}},
    });
    const session: ChatSession = {
      sessionId: 's1',
      userId: 'u1',
      entries: [{role: 'user', content: 'hi', timestamp: ''}],
    };

    await engine.orchestrator.processMessage(session);

    expect(seen).toEqual(['beforeSession']);
  });

  it('forwards transport.port, so the server listens where the config said', async () => {
    const engine = createHalEngine({...base, transport: {port: 0}});

    await engine.start();
    const address = engine.server.address();
    const port = typeof address === 'object' && address !== null ? address.port : -1;
    await engine.stop();

    expect({usedTheConfig: port !== 8086, real: port > 0}).toEqual({usedTheConfig: true, real: true});
  });

  it('lets an explicit start(port) win over the configured one', async () => {
    const engine = createHalEngine({...base, transport: {port: 8099}});

    await engine.start(0);
    const address = engine.server.address();
    const port = typeof address === 'object' && address !== null ? address.port : -1;
    await engine.stop();

    expect({usedTheArgument: port !== 8099, real: port > 0}).toEqual({usedTheArgument: true, real: true});
  });
});

// The option was declared on HalEngineConfig and read by nothing, so a supplied logger received no lines.
describe('createHalEngine logger forwarding', () => {
  afterEach(() => {
    setLogger();
  });

  it("delivers the package's own log lines to a supplied logger", async () => {
    const lines: {category: string; message: string}[] = [];
    const collect = (category: string, message: string) => void lines.push({category, message});
    const logger: Logger = {debug: collect, info: collect, warn: collect, error: collect};

    const engine = createHalEngine({...base, logger, transport: {port: 0}});
    await engine.start();
    await engine.stop();

    expect(lines).toContainEqual({category: 'server', message: 'HAL Engine started'});
  });

  // Asserts on a line logged AFTER construction: nothing logs during it, so an emptiness check cannot fail.
  it('leaves an already-supplied logger in place when the config names none', async () => {
    const lines: string[] = [];
    setLogger({
      debug: (_c: string, m: string) => void lines.push(m),
      info: (_c: string, m: string) => void lines.push(m),
      warn: (_c: string, m: string) => void lines.push(m),
      error: (_c: string, m: string) => void lines.push(m),
    });

    createHalEngine({...base});
    log.info('test', 'after construction');

    expect(lines).toEqual(['after construction']);
  });
});

describe('createHalEngine orchestrator hooks reach the orchestrator', () => {
  it('processes a message when the config declares no orchestrator key at all', async () => {
    const engine = createHalEngine({...base});
    const session: ChatSession = {
      sessionId: 's-noorch',
      userId: 'u1',
      entries: [{role: 'user', content: 'ping', timestamp: ''}],
    };

    const reply = await engine.orchestrator.processMessage(session);

    expect(reply).toContain('ping');
  });

  it('hands a config-installed beforeModelResponse hook the built base system prompt, not merely storing it', async () => {
    let received = 'never called';
    const engine = createHalEngine({
      ...base,
      orchestrator: {
        hooks: {
          beforeModelResponse: async (_session, systemPrompt) => {
            received = systemPrompt;
            return systemPrompt;
          },
        },
      },
    });
    const session: ChatSession = {
      sessionId: 's-prompt',
      userId: 'u1',
      entries: [{role: 'user', content: 'hi', timestamp: ''}],
    };

    await engine.orchestrator.processMessage(session);

    expect(received).toBe('test');
  });

  it('fires the lifecycle hooks in documented order for a session that completes without error', async () => {
    const order: string[] = [];
    const engine = createHalEngine({
      ...base,
      orchestrator: {
        hooks: {
          beforeSession: async () => void order.push('beforeSession'),
          beforeUserInput: async (_session, message) => {
            order.push('beforeUserInput');
            return message;
          },
          afterUserInput: async () => void order.push('afterUserInput'),
          beforeModelResponse: async (_session, systemPrompt) => {
            order.push('beforeModelResponse');
            return systemPrompt;
          },
          afterModelResponse: async () => void order.push('afterModelResponse'),
          afterSession: async () => void order.push('afterSession'),
        },
      },
    });
    const session: ChatSession = {
      sessionId: 's-order',
      userId: 'u1',
      entries: [{role: 'user', content: 'hello', timestamp: ''}],
    };

    await engine.orchestrator.processMessage(session);

    expect(order).toEqual([
      'beforeSession',
      'beforeUserInput',
      'afterUserInput',
      'beforeModelResponse',
      'afterModelResponse',
      'afterSession',
    ]);
  });
});

// An unavailable port is a condition a consumer can handle, but only if start() lets them see it.
describe('createHalEngine on a port it cannot bind', () => {
  it('rejects instead of taking the process down with an unhandled error event', async () => {
    const blocker = net.createServer();
    await new Promise<void>(resolve => blocker.listen(0, resolve));
    const taken = (blocker.address() as net.AddressInfo).port;
    const engine = createHalEngine({...base, transport: {port: taken}});

    await expect(engine.start()).rejects.toMatchObject({code: 'EADDRINUSE'});

    await new Promise<void>(resolve => blocker.close(() => resolve()));
  });
});

